// Filtrar y validar clientes activos
const items = $input.all();
const activeClients = [];
const errors = [];

for (const item of items) {
  const cliente = item.json;

  // Validaciones
  if (cliente.activo !== 'SI') {
    continue;
  }

  if (!cliente.email_cliente || !cliente.email_cliente.includes('@')) {
    errors.push(`${cliente.cliente || 'Sin nombre'}: email inválido`);
    continue;
  }

  if (!cliente.monto_base || cliente.monto_base <= 0) {
    errors.push(`${cliente.cliente}: monto inválido`);
    continue;
  }

  activeClients.push(item);
}

console.log(`Clientes válidos: ${activeClients.length}`);
console.log(`Clientes con errores: ${errors.length}`);

if (errors.length > 0) {
  console.log('Errores encontrados:', errors.join(', '));
}

return activeClients;

// Calcular totales de facturación con validaciones
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Obtener valores con defaults
  const montoBase = parseFloat(data.monto_base) || 0;
  const ivaRate = parseFloat(data.iva_rate) || 0.21;
  const diasVencimiento = parseInt(data.dias_vencimiento) || 30;

  // Calcular IVA y total (redondeo a 2 decimales)
  const ivaMonto = Math.round(montoBase * ivaRate * 100) / 100;
  const montoTotal = Math.round((montoBase + ivaMonto) * 100) / 100;

  // Generar ID único de factura
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const random = Math.random().toString(36).substring(2, 8).toUpperCase();
  const invoiceId = `FAC-${year}${month}-${random}`;

  // Calcular fechas
  const fechaEmision = now.toISOString().split('T')[0];
  const vencimiento = new Date(now.getTime() + diasVencimiento * 24 * 60 * 60 * 1000);
  const fechaVencimiento = vencimiento.toISOString().split('T')[0];

  // Formatear fechas para mostrar
  const fechaEmisionFormato = `${day}/${month}/${year}`;
  const vencimientoDay = String(vencimiento.getDate()).padStart(2, '0');
  const vencimientoMonth = String(vencimiento.getMonth() + 1).padStart(2, '0');
  const vencimientoYear = vencimiento.getFullYear();
  const fechaVencimientoFormato = `${vencimientoDay}/${vencimientoMonth}/${vencimientoYear}`;

  results.push({
    json: {
      // Datos originales
      row_id_en_sheets: data.row_id_en_sheets,
      cliente: data.cliente,
      email_cliente: data.email_cliente,
      concepto: data.concepto || `Servicios correspondientes a ${month}/${year}`,
      forma_pago: data.forma_pago || 'Transferencia bancaria',
      notas: data.notas || '',

      // Datos calculados
      invoice_id: invoiceId,
      monto_base: montoBase,
      iva_rate: ivaRate,
      iva_monto: ivaMonto,
      monto_total: montoTotal,
      fecha_emision: fechaEmision,
      fecha_vencimiento: fechaVencimiento,
      fecha_emision_formato: fechaEmisionFormato,
      fecha_vencimiento_formato: fechaVencimientoFormato,
      moneda: 'EUR',
      periodo: `${year}-${month}`,

      // Para email
      iva_porcentaje: Math.round(ivaRate * 100),

      // Metadata
      timestamp_generacion: now.toISOString()
    }
  });
}

console.log(`Facturas generadas: ${results.length}`);
return results;

// Actualizar datos del cliente con estado
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  results.push({
    json: {
      row_id_en_sheets: data.row_id_en_sheets,
      estado: `Emitida ${data.fecha_emision_formato}`,
      fecha_ultima_factura: data.fecha_emision
    }
  });
}

return results;

// Generar resumen estadístico del proceso
const items = $input.all();

let totalBase = 0;
let totalIVA = 0;
let totalFacturado = 0;
const detalles = [];
const clientesNombres = [];

for (const item of items) {
  totalBase += item.json.monto_base;
  totalIVA += item.json.iva_monto;
  totalFacturado += item.json.monto_total;

  detalles.push({
    cliente: item.json.cliente,
    factura: item.json.invoice_id,
    total: item.json.monto_total.toFixed(2),
    fecha: item.json.fecha_emision_formato
  });

  clientesNombres.push(item.json.cliente);
}

const now = new Date();
const periodo = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
const fechaFormato = `${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

return [{
  json: {
    periodo,
    fecha: fechaFormato,
    fecha_iso: now.toISOString(),
    total_facturas: items.length,
    total_base: totalBase.toFixed(2),
    total_iva: totalIVA.toFixed(2),
    total_facturado: totalFacturado.toFixed(2),
    promedio_factura: (totalFacturado / items.length).toFixed(2),
    clientes_list: clientesNombres.join(', '),
    detalles_html: detalles.map(d => 
      `<tr>
        <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb;">${d.cliente}</td>
        <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb;">${d.factura}</td>
        <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; text-align: center;">${d.fecha}</td>
        <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; text-align: right; font-weight: bold; color: #10b981;">${d.total} €</td>
      </tr>`
    ).join('')
  }
}];
